CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE memory_scopes(scope_id TEXT PRIMARY KEY,revision BIGINT NOT NULL DEFAULT 0);
CREATE TABLE memory_jobs(id UUID PRIMARY KEY,scope_id TEXT NOT NULL,viewer_id UUID NOT NULL,source TEXT NOT NULL,event_id TEXT NOT NULL,body TEXT NOT NULL,occurred_at_ms BIGINT NOT NULL,day BIGINT NOT NULL,state TEXT NOT NULL DEFAULT 'pending',attempts INT NOT NULL DEFAULT 0,available_at_ms BIGINT NOT NULL,lease_until_ms BIGINT,token UUID,revision BIGINT NOT NULL DEFAULT 0,UNIQUE(scope_id,source,event_id),FOREIGN KEY(scope_id,viewer_id) REFERENCES viewers(scope_id,id));
CREATE INDEX memory_jobs_ready ON memory_jobs(scope_id,state,available_at_ms);
CREATE TABLE memories(id UUID PRIMARY KEY,scope_id TEXT NOT NULL,viewer_id UUID NOT NULL,key TEXT NOT NULL,value TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,version BIGINT NOT NULL DEFAULT 1,locked BOOLEAN NOT NULL DEFAULT false,deleted BOOLEAN NOT NULL DEFAULT false,created_at_ms BIGINT NOT NULL,updated_at_ms BIGINT NOT NULL,expires_at_ms BIGINT,UNIQUE(scope_id,id),FOREIGN KEY(scope_id,viewer_id) REFERENCES viewers(scope_id,id));
CREATE INDEX memories_viewer ON memories(scope_id,viewer_id,key);
CREATE TABLE memory_evidence(scope_id TEXT NOT NULL,memory_id UUID NOT NULL,source TEXT NOT NULL,event_id TEXT NOT NULL,quote TEXT NOT NULL,occurred_at_ms BIGINT NOT NULL,day BIGINT NOT NULL,PRIMARY KEY(scope_id,memory_id,source,event_id),FOREIGN KEY(scope_id,memory_id) REFERENCES memories(scope_id,id));
CREATE TABLE memory_suppressions(scope_id TEXT NOT NULL,viewer_id UUID NOT NULL,key TEXT NOT NULL,source TEXT NOT NULL DEFAULT '',event_id TEXT NOT NULL DEFAULT '',PRIMARY KEY(scope_id,viewer_id,key,source,event_id));
CREATE TABLE memory_audit(scope_id TEXT NOT NULL,request_key TEXT NOT NULL,memory_id UUID NOT NULL,viewer_id UUID NOT NULL,operation TEXT NOT NULL,value TEXT,reason TEXT NOT NULL,actor TEXT NOT NULL,expected_version BIGINT NOT NULL,created_at_ms BIGINT NOT NULL,PRIMARY KEY(scope_id,request_key));
CREATE TABLE memory_tombstones(scope_id TEXT NOT NULL,memory_id UUID NOT NULL,version BIGINT NOT NULL,created_at_ms BIGINT NOT NULL,PRIMARY KEY(scope_id,memory_id));
CREATE TABLE memory_vectors(scope_id TEXT NOT NULL,memory_id UUID NOT NULL,version BIGINT NOT NULL,model TEXT NOT NULL,dimensions INT NOT NULL CHECK(dimensions BETWEEN 1 AND 4096),embedding vector NOT NULL,CHECK(vector_dims(embedding)=dimensions),PRIMARY KEY(scope_id,memory_id,model,dimensions),FOREIGN KEY(scope_id,memory_id) REFERENCES memories(scope_id,id));
CREATE TABLE memory_embedding_jobs(scope_id TEXT NOT NULL,memory_id UUID NOT NULL,version BIGINT NOT NULL,model TEXT NOT NULL,dimensions INT NOT NULL,token UUID NOT NULL,lease_until_ms BIGINT NOT NULL,attempts INT NOT NULL DEFAULT 1,PRIMARY KEY(scope_id,memory_id,model,dimensions));
